import { DomainError } from "../domain/DomainError";
import { Order } from "../domain/Order";
import { OrderRepository } from "../domain/OrderRepository";
import { OrderStatus } from "../domain/OrderStatus";
import { ProductRepository } from "../domain/ProductRepository";
import { CreateOrderInput, OrderDto } from "./OrderDtos";

export class OrderService {
  public constructor(
    private readonly orders: OrderRepository,
    private readonly products: ProductRepository,
  ) {}

  public placeOrder(input: CreateOrderInput): OrderDto {
    const quantities = this.combineItems(input);
    const order = new Order(this.newId(), input.customerId, quantities);
    const reserved: { productId: string; quantity: number }[] = [];
    try {
      for (const item of quantities) {
        const product = this.products.findById(item.productId);
        if (!product) throw new DomainError(`Product ${item.productId} was not found`);
        product.reserve(item.quantity);
        reserved.push(item);
      }
    } catch (error) {
      for (const item of reserved) this.products.findById(item.productId)?.release(item.quantity);
      throw error;
    }
    this.orders.save(order);
    return this.toDto(order);
  }

  public advanceOrder(orderId: string, status: OrderStatus): OrderDto {
    const order = this.getOrder(orderId);
    order.advanceTo(status);
    this.orders.save(order);
    return this.toDto(order);
  }

  public cancelOrder(orderId: string): OrderDto {
    const order = this.getOrder(orderId);
    order.cancel();
    for (const line of order.lines) {
      const product = this.products.findById(line.productId);
      if (!product) throw new DomainError(`Product ${line.productId} was not found`);
      product.release(line.quantity);
    }
    this.orders.save(order);
    return this.toDto(order);
  }

  public listOrders(status?: OrderStatus): OrderDto[] {
    return this.orders.listByStatus(status).map((order) => this.toDto(order));
  }

  private getOrder(id: string): Order {
    const order = this.orders.findById(id);
    if (!order) throw new DomainError(`Order ${id} was not found`);
    return order;
  }

  private combineItems(input: CreateOrderInput): { productId: string; quantity: number }[] {
    const quantities = new Map<string, number>();
    for (const item of input.items) {
      if (!item.productId || !Number.isInteger(item.quantity) || item.quantity <= 0) {
        throw new DomainError("Each item needs a product and a positive integer quantity");
      }
      quantities.set(item.productId, (quantities.get(item.productId) ?? 0) + item.quantity);
    }
    return [...quantities].map(([productId, quantity]) => ({ productId, quantity }));
  }

  private newId(): string {
    return `order-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
  }

  private toDto(order: Order): OrderDto {
    return {
      id: order.id,
      customerId: order.customerId,
      status: order.currentStatus,
      cancelled: order.isCancelled,
      items: order.lines.map((line) => ({ ...line })),
    };
  }
}

